\u0020\u0033\u006a\u0037\u0058\u002a\u004c\u005f\u005e\u0025\u004c\u0078\u002d\u006e\u004b\u007a\u005e\u0078\u0067\u004f\u006f\u0030\u0039\u0071\u004c\u003d\u0054\u007b\u006d\u0052\u003e\u0022\u0027\u0022\u0036\u0036\u005c\u0034\u005f\u0053\u006d\u0024\u006d\u006d\u0074\u0055\u002d\u0077\u006e\u005f\u006a\u0069\u006b\u003f\u006d\u005a\u0044\u007b\u0055\u0049\u0069\u0051\u005b\u0024\u0055\u0048\u003b\u0063\u006e\u007a\u0023\u004c\u0079\u0037\u0067\u0063\u006e\u0021\u002c\u0029\u006c\u003e\u0026\u0067\u004a\u003c\u003b\u0067\u006c\u0072\u003d\u0021\u007c\u004d\u0071\u0040\u0022\u0035\u003e\u004f\u006b\u0079\u0034\u007e\u002b\u0033\u0066\u0060\u0056\u0031\u0071\u003b\u0075\u005a\u0069\u0055\u003e\u0033\u0039\u0066\u0057\u0022\u002f\u0023\u0069\u0044\u004c\u005b\u005d\u0072\u004d\u0041\u0055\u0028\u0054\u0063\u0037\u0058\u0028\u0042\u0059\u0055\u0024\u0020\u0055\u006a\u0044\u002d\u005f\u006a\u0056\u0078\u0022\u003a\u007e\u0040\u0061\u0030\u0042\u0068\u0074\u0077\u0025\u0020\u0045\u0074\u005e\u0044\u0064\u002a\u0072\u0078\u0074\u003d\u0029\u0063\u0047\u002c\u0054\u006a\u005c\u0046\u003b\u0074\u0030\u0025\u005e\u0036\u0057\u006f\u0031\u007d\u0048\u004a\u0026\u005d\u0063\u0022\u0056\u003e\u0038\u002b\u006c\u003b\u0058\u0061\u006e\u0030\u0027\u0061\u0025\u0060\u0057\u0024\u0034\u007c\u0059\u005a\u0075\u0040\u0071\u004a\u004d\u0048\u0021\u002d\u0023\u0037\u0064\u0053\u006e\u0069\u0029\u0052\u007d\u0069\u0045\u0058\u0021\u0061\u004b\u004b\u0029\u006b\u002f\u0058\u003f\u0034\u006e\u0078\u0042\u0057\u0074\u007e\u002b\u0058\u0043\u0053\u0058\u0031\u0036\u006f\u0055\u0046\u0030\u006b\u0045\u004f\u0023\u0075\u0044\u0027\u005a\u0022\u0049\u003f\u005e\u0037\u0033\u0043\u0034\u0050\u007d\u0079\u004d\u0041\u0067\u0072\u0058\u003c\u0074\u0047\u0036\u003b\u0020\u0031\u0063\u0059\u0064\u0033\u0061\u003c\u002d\u0061\u0054\u004e\u007b\u0062\u0048\u0072\u0052\u0064\u005f\u004c\u0069\u0028\u007c\u006f\u0065\u003e\u0071\u006a\u006c\u004a\u003a\u006b\u0026\u0071\u0068\u007a\u0023\u0068\u0031\u005f\u0069\u003f\u0047\u0031\u006f\u0058\u0041\u003a\u0030\u003a\u0067\u0040\u0052\u0037\u006f\u0070\u0032\u0078\u0076\u003e\u0075\u0068\u0067\u005c\u0039\u004c\u0061\u006d\u0058\u0063\u0034\u0046\u0074\u0039\u0042\u0060\u006e\u0046\u0068\u0030\u0060\u0039\u0045\u005a\u0041\u0060\u0043\u0071\u0064\u0039\u0058\u0061\u0053\u0052\u006e\u007a\u0070\u0033\u006a\u002c\u006b\u007c\u0067\u003f\u0036\u0031\u0029\u0076\u0068\u0063\u0063\u002a\u0063\u0059\u002c\u004c\u005a\u0061\u0027\u0062\u007e\u0022\u0037\u0074\u0030\u0041\u0041\u0041\u0045\u006b\u0021\u0064\u006d\u003b\u007e\u006d\u007d\u003b\u0068\u0053\u0022\u0036\u006c\u0079\u006a\u0040\u0043\u007d\u002b\u0039\u004a\u0077\u0034\u005a\u006f\u0052\u004f\u0039\u004e\u002f\u0028\u0037\u0059\u0074\u003f\u0070\u0063\u0034\u002e\u006b\u005d\u0021\u0039\u0039\u0036\u0060\u004f\u003c\u0076\u004e\u007d\u002f\u007c\u0068\u0040\u005d\u002b\u005f\u0037\u002d\u0077\u0048\u0021\u0057\u007c\u004b\u007d\u0069\u007e\u002b\u0075\u006b\u0040\u0061\u006b\u003d\u007c\u0070\u005b\u0023\u0072\u0054\u0021\u0039\u0066\u0061\u003a\u006c\u0076\u0037\u0020\u0059\u007e\u0023\u0043\u004c\u0047\u0069\u004e\u0033\u0023\u0031\u0028\u004c\u0025\u007e\u0050\u006c\u005b\u007d\u0023\u0056\u0055\u005a\u0050\u0048\u0051\u004a\u0048\u0043\u003f\u007d\u0048\u0039\u006f\u0031\u002c\u0070\u007e\u0059\u002f\u0060\u0041\u005a\u0063\u0068\u0032\u0036\u004f\u004e\u0060\u0054\u005c\u0044\u002d\u0060\u0078\u006b\u0073\u004a\u005d\u002a\u0054\u0047\u0027\u006b\u002b\u0056\u007d\u004e\u0049\u0049\u0052\u0045\u0057\u0052\u0049\u003e\u002a\u003f\u004c\u0066\u007e\u0072\u0033\u0025\u0064\u0078\u005a\u0074\u0050\u007a\u005c\u0044\u0045\u004a\u0028\u0068\u003b\u0035\u0046\u0041\u006d\u0040\u0049\u0031\u005e\u0058\u002a\u0028\u0063\u007c\u002e\u002f\u0075\u0046\u0035\u003e\u0044\u0054\u0052\u006e\u006c\u0021\u0040\u0075\u004e\u006f\u0024\u0069\u0031\u002e\u0072\u003c\u0078\u0068\u0028\u0033\u005c\u0046\u0052\u003c\u0047\u0035\u0063\u006c\u0067\u005f\u002a\u0027\u003a\u004e\u0057\u0073\u004a\u007d\u0030\u0066\u0073\u006f\u006a\u0065\u005d\u0072\u005c\u007d\u0031\u0041\u007c\u0038\u0060\u007d\u003b\u0068\u0066\u007c\u003e\u004b\u0058\u004f\u007e\u006f\u0068\u003f\u0041\u0047\u0030\u0027\u0046\u0071\u004b\u007c\u0035\u0055\u0040\u006f\u0040\u0028\u007a\u002c\u004a\u0029\u0042\u004a\u006e\u0049\u0037\u0068\u0042\u0079\u0070\u007a\u007c\u0039\u0045\u0055\u0045\u005b\u0061\u0034\u004e\u0052\u004f\u0022\u0027\u0052\u005d\u0040\u0074\u0077\u0060\u006e\u007d\u0024\u004a\u0070\u007e\u005b\u005f\u0043\u002b\u006d\u002b\u0035\u0063\u006a\u003a\u006a\u0052\u0033\u006e\u0073\u007b\u0024\u005a\u0042\u004c\u0067\u002c\u0053\u0048\u002c\u0048\u0072\u002c\u006c\u006d\u002b\u003d\u0020\u0026\u004a\u0043\u0049\u005d\u005e\u007b\u0030\u0053\u004d\u0061\u0040\u0068\u0052\u0028\u0054\u0053\u0062\u0050\u006c\u004f\u0025\u007e\u0026\u0035\u005c\u0053\u005a\u0028\u005f\u0055\u006f\u0059\u0044\u0047\u006b\u0060\u0065\u0046\u0065\u0038\u0037\u0063\u0037\u0044\u002b\u0067\u003a\u0054\u002e\u007e\u0036\u0067\u007c\u006c\u0057\u006c\u0047\u006b\u0042\u005a\u007e\u0074\u006b\u002d\u0071\u0078\u0058\u006e\u003d\u006d\u0023\u0063\u002a\u0035\u0020\u0036\u0046\u0037\u007b\u0036\u0060\u002a\u0025\u006c\u0059\u0045\u0069\u007a\u003b\u005c\u002d\u0074\u0057\u006c\u0030\u0052\u003c\u004e\u005a\u004a\u003e\u0072\u0054\u0038\u0067\u005b\u006d\u0059\u0050\u006b\u0045\u0023\u0034\u0046\u004c\u0044\u002e\u0061\u0026\u0026\u007a\u0065\u006b\u0037\u0078\u0045\u006e\u0069\u0069\u0072\u006d\u0057\u004e\u004b\u0063\u002a\u0076\u0048\u0028\u004e\u0048\u004e\u0021\u0066\u0058\u003c\u0031\u0056\u0048\u005f\u0045\u0022\u005d\u003f\u0040\u0025\u0053\u0079\u005e\u0021\u0074\u0036\u0042\u0076\u0025\u0070\u0047\u0059\u0044\u003d\u0020\u0025\u0048\u003d\u0040\u003a\u003f\u0056\u003e\u0049\u0069\u0022\u0046\u0032\u0059\u0041\u0033\u002d\u0071\u0040\u002b\u0073\u0022\u0020\u003d\u0057\u0024\u003c\u0072\u005e\u0037\u0042\u0078\u0079\u0070\u003c\u006a\u006f\u005f\u0051\u005f\u005f\u0066\u0075\u003d\u006c\u0051\u0062\u006e\u0062\u006f\u0043\u006e\u0030\u0028\u0056\u0071\u005d\u0038\u003d\u0026\u0077\u0028\u0020\u0040\u0044\u002c\u0076\u005b\u0030\u0042\u002c\u0053\u0066\u007c\u0030\u0050\u004c\u004d\u0050\u0030\u004f\u0068\u0068\u0063\u0059\u0061\u0071\u0023\u004d\u0050\u0027\u0020\u0033\u004a\u0061\u006d\u0045\u002c\u003c\u0054\u006e\u004c\u002f\u0031\u0052\u0061\u007d\u0043\u0043\u004c\u0059\u0070\u006a\u003e\u0028\u0040\u007a\u003a\u0075\u0069\u002f\u0041\u0066\u0044\u0051\u002c\u005d\u0040\u004a\u0020\u0042\u0028\u004f\u0073\u0061\u0024\u0076\u0041\u007c\u002a\u004b\u0034\u007d\u006d\u0079\u006e\u0032\u0058\u003b\u0056\u0029\u0045\u007e\u002c\u004e\u0074\u0020\u0061\u003c\u0022\u005b\u0061\u002c\u0050\u0079\u0055\u0053\u0063\u0027\u0069\u0031\u0058\u002c\u0042\u0035\u002d\u0027\u002d\u004a\u0032\u0058\u004a\u0061\u0043\u0041\u004b\u0055\u005f\u0075\u003d\u003f\u0046\u004e\u0067\u0060\u005e\u004b\u007d\u003a\u0059\u0067\u0073\u0027\u004c\u0039\u005a\u0072\u0033\u0039\u0030\u0070\u006f\u002c\u0074\u0054\u007e\u003a\u0071\u006e\u006d\u0056\u002a\u0063\u0049\u0034\u0046\u006c\u0062\u0073\u0031\u004c\u0054\u0077\u0059\u0026\u0033\u0046\u003f\u005f\u0067\u004f\u0060\u0026\u0048\u0040\u0036\u0056\u003a\u004a\u003e\u0032\u0052\u0060\u002d\u0068\u0057\u0042\u0072\u0052\u004a\u002b\u0045\u004f\u007b\u0050\u0063\u0066\u006e\u007a\u0030\u0024\u004e\u004d\u0048\u0022\u003f\u0069\u006f\u0071\u004c\u0031\u007d\u0057\u004c\u004b\u0049\u0067\u0062\u0058\u007a\u004c\u006a\u0078\u0048\u0051\u005d\u005d\u0059\u003f\u004d\u0033\u0021\u0043\u007b\u0043\u0075\u0078\u004d\u0037\u007a\u002f\u004c\u002c\u0060\u004c\u006c\u002f\u0079\u006e\u0054\u0055\u0025\u005e\u0058\u0076\u0021\u0035\u004c\u003c\u0032\u0042\u0033\u0067\u0048\u004f\u0060\u0064\u007e\u0052\u007a\u0031\u007e\u003e\u0071\u0050\u0059\u003f\u007c\u0037\u005e\u0038\u0069\u0038\u0052\u003c\u002c\u0023\u0039\u0024\u0075\u002e\u003c\u005f\u005d\u0046\u0074\u006c\u0049\u002b\u0030\u0041\u002d\u003d\u006e\u0043\u003a\u0027\u0031\u007c\u0054\u0025\u004a\u0067\u004e\u005e\u0025\u0054\u004c\u003f\u0027\u0043\u0033\u004c\u0069\u0041\u006c\u004b\u0021\u0056\u005e\u005e\u0034\u0074\u0046\u002b\u0064\u006f\u007c\u0051\u0034\u0071\u0071\u003c\u0025\u0062\u007b\u003c\u007b\u0070\u005f\u0054\u007c\u0076\u0075\u0064\u0022\u0063\u0078\u0047\u006a\u002d\u0068\u0039\u0067\u005c\u0029\u004d\u0062\u002d\u0070\u0037\u0078\u004b\u0039\u0038\u003a\u0067\u003c\u0057\u006d\u0073\u007c\u002f\u002d\u0049\u0020\u003a\u006b\u0027\u006b\u005e\u0052\u002a\u003a\u0060\u0020\u0053\u006a\u003c\u0026\u004d\u005f\u0021\u0057\u0072\u0056\u0035\u005f\u0067\u0042\u0038\u0077\u003a\u004a\u004a\u0032\u005c\u0038\u0066\u003e\u0042\u005e\u0031\u005a\u0071\u0029\u002e\u0040\u0047\u007a\u0073\u0029\u0054\u0060\u003c\u005d\u0031\u0077\u0049\u0077\u0039\u004b\u0061\u0057\u0065\u005f\u006b\u0059\u0028\u0035\u0063\u0038\u0043\u0067\u006f\u004f\u0039\u004a\u002e\u0074\u0038\u0047\u0049\u0078\u0028\u006b\u003b\u0064\u005d\u0078\u0079\u0057\u003c\u003e\u003e\u005b\u004f\u006f\u0069\u003e\u002c\u0039\u0025\u0043\u0025\u004e\u0077\u006a\u0045\u0076\u0020\u0020\u002e\u0037\u005d\u0052\u002d\u002c\u0035\u0066\u0077\u0032\u0043\u002d\u004c\u0033\u0036\u0051\u0038\u0035\u0061\u0079\u005c\u002c\u004c\u002e\u0063\u0076\u003a\u0021\u0025\u0045\u002b\u0027\u005f\u002a\u0022\u0077\u0071\u0061\u0036\u004a\u007c\u0072\u006f\u0045\u0026\u0044\u0023\u003f\u005a\u0075\u006c\u0040\u0056\u006b\u005c\u002a\u0056\u003c\u0064\u0052\u0066\u0026\u0048\u003a\u0028\u007a\u003d\u0040\u0062\u0065\u007e\u0072\u0034\u002c\u0048\u004f\u0029\u002f\u003c\u002f\u0036\u0042\u005a\u0041\u0067\u003a\u0064\u0029\u003a\u0034\u0056\u006a\u002a\u005b\u002f\u003f\u0043\u005d\u0065\u0058\u005e\u0041\u004a\u0053\u0045\u007b\u006a\u002c\u007a\u005e\u002e\u0029\u003d\u0078\u0036\u0036\u0052\u006f\u0052\u0073\u005c\u007a\u0026\u0023\u0075\u0032\u0047\u0036\u0036\u005a\u0055\u0026\u0025\u006d\u0038\u0029\u004b\u0020\u0070\u0043\u004a\u004b\u007a\u003d\u0067\u0026\u0020\u0052\u007b\u0077\u003e\u007c\u003a\u0059\u0027\u007d\u003b\u0048\u005c\u003f\u0030\u0039\u007a\u0046\u0048\u007c\u003b\u006c\u006a\u007c\u0055\u0049\u0062\u0050\u0035\u0030\u004d\u0070\u0066\u0039\u007d\u0035\u006b\u0035\u0057\u0052\u0033\u0073\u006c\u0045\u006d\u005e\u0076\u007b\u0058\u004b\u0054\u0035\u0047\u0029\u0073\u006c\u0072\u0033\u002c\u003d\u0025\u005b\u0034\u006b\u005d\u0027\u006c\u0069\u005f\u0068\u0023\u0057\u0048\u0022\u0022\u0037\u0045\u003d\u006b\u007b\u0029\u0047\u002d\u0037\u0027\u0048\u0056\u0058\u004d\u0054\u0068\u0046\u002d\u003c\u005e\u0055\u0055\u007e\u006b\u0064\u0035\u004e\u006a\u0073\u0038\u005e\u0032\u0037\u0067\u0037\u002d\u003c\u002f\u0023\u0042\u005e\u0055\u006e\u0049\u006c\u0078\u002b\u0044\u0040\u0063\u0031\u0026\u0031\u0067\u0028\u0078\u0054\u007d\u004b\u0042\u006c\u0044\u0024\u0077\u0066\u002c\u002c\u0026\u006d\u007d\u0072\u0033\u002d\u007d\u003a\u0074\u0067\u0076\u0058\u0064\u006b\u007d\u005b\u0042\u004b\u0034\u002f\u0062\u0070\u0040\u0046\u007e\u0054\u0034\u004e\u0038\u0028\u0035\u0067\u006a\u006c\u0038\u007d\u003f\u007b\u0031\u004c\u0047\u006b\u0060\u0075\u007a\u0063\u0046\u0033\u0050\u0060\u0027\u0044\u0024\u002c\u0037\u007b\u004e\u0040\u003c\u0054\u0033\u005e\u0048\u0068\u0055\u002d\u0044\u006b\u0065\u0031\u007a\u0020\u0040\u006d\u0027\u002d\u0028\u006c\u003a\u0020\u0022\u0036\u002b\u002f\u0075\u004b\u0048\u002e\u0067\u0068\u003d\u0034\u0021\u0065\u007c\u007c\u0047\u0071\u0024\u006e\u0045\u006d\u005d\u0056\u0058\u005e\u0042\u0063\u0026\u007a\u0021\u0047\u0065\u006e\u0052\u0056\u0031\u0069\u0049\u0070\u002d\u002c\u0048\u0029\u005b\u0053\u0031\u007b\u0069\u0053\u0077\u0034\u0059\u0023\u0063\u0029\u0074\u0076\u0069\u004f\u0058\u0043\u004f\u0033\u007a\u007a\u0058\u006f\u0040\u0022\u0060\u005c\u0046\u0031\u005a\u0075\u003f\u0070\u0073\u0073\u004d\u0030\u0072\u0021\u0055\u0021\u007b\u0025\u0037\u007d\u0026\u005d\u0063\u007b\u0042\u007e\u004b\u0072\u0058\u004d\u0044\u0075\u0051\u0078\u0059\u0073\u0022\u0028\u0072\u006a\u006f\u0048\u007b\u0069\u006b\u0026\u0078\u003b\u0047\u002f\u0046\u005f\u007a\u0050\u0064\u0055\u0078\u0050\u0034\u003e\u003c\u007a\u007d\u002f\u0022\u004e\u0068\u003d\u004b\u0056\u004f\u0025\u0024\u0073\u0079\u004d\u0045\u007c\u006a\u0063\u0053\u003a\u0039\u0066\u0045\u004a\u004d\u0048\u0040\u006a\u0028\u003d\u0037\u0050\u0055\u0057\u007a\u004b\u0039\u0076\u0045\u0027\u0029\u0033\u0048\u0040\u005b\u0070\u0055\u002e\u002c\u007a\u005e\u005e\u0053\u0051\u0028\u0077\u0056\u0025\u006f\u0022\u0051\u007c\u0023\u0041\u0055\u0073\u006f\u003c\u0071\u0045\u002f\u0077\u005e\u0028\u003c\u0054\u002d\u002a\u0048\u0028\u0078\u0028\u0021\u0070\u004f\u0064\u0055\u0040\u0046\u005c\u005e\u0055\u0028\u002b\u004d\u0060\u0066\u0040\u0059\u0021\u007e\u0051\u0055\u004f\u0035\u005e\u0028\u0066\u0029\u0025\u004b\u0023\u0065\u0026\u005e\u003c\u0056\u0075\u0075\u007b\u002b\u0053\u0049\u005b\u0073\u0063\u0048\u0058\u0023\u0048\u0044\u006e\u005b\u0063\u0071\u0072\u0055\u0029\u0039\u0042\u0068\u005e\u0066\u0041\u003b\u003d\u0032\u0066\u0044\u0060\u003a\u0023\u0036\u005e\u007d\u0059\u0067\u0049\u003f\u0023\u0030\u0054\u007b\u0040\u0044\u0079\u007e\u006c\u005c\u0022\u0058\u004b\u0058\u003d\u0035\u006d\u0031\u0074\u0079\u0067\u0032\u005f\u003c\u003a\u004b\u0064\u003a\u0041\u0078\u005b\u0068\u0048\u0063\u005a\u004c\u0050\u0033\u0041\u0027\u0067\u005b\u003a\u002d\u004c\u0070\u005d\u004a\u003c\u002c\u002a\u002e\u0026\u005e\u0052\u0051\u0079\u0023\u0042\u0053\u0022\u006d\u0077\u005b\u0026\u006b\u0069\u0027\u007d\u0041\u0028\u003b\u007b\u002d\u0032\u0021\u003f\u006b\u002c\u007c\u005a\u006e\u004e\u0047\u0067\u0074\u0076\u007b\u003c\u007e\u0043\u0072\u005c\u0065\u0057\u0029\u003f\u003c\u0056\u0054\u0047\u0063\u005c\u006f\u0060\u0041\u004d\u003a\u0047\u0056\u004b\u007c\u0038\u0066\u002d\u004a\u0045\u0061\u0065\u004a\u002b\u007c\u0053\u005c\u005b\u003b\u0030\u0069\u007c\u0051\u003a\u0054\u007e\u0042\u002f\u003a\u0030\u0034\u0037\u007b\u0040\u0076\u004b\u004d\u002c\u0054\u0067\u0075\u0061\u0024\u0048\u0060\u0057\u004e\u0032\u007e\u0079\u0074\u0069\u006e\u0063\u0065\u0070\u0076\u0077\u0041\u0078\u004a\u0065\u0078\u005c\u006c\u0043\u0024\u002f\u006f\u0069\u0051\u0034\u0040\u0046\u002b\u0072\u0073\u002f\u0021\u007c\u0051\u0026\u0044\u003b\u0040\u0051\u0051\u007d\u0079\u004b\u005c\u0038\u002e\u0055\u0076\u0059\u0077\u002d\u0039\u0050\u004e\u0023\u0043\u0037\u005c\u0027\u006a\u006d\u0043\u0021\u002a\u006a\u002f\u0025\u0049\u005f\u0043\u005d\u0020\u0043\u0068\u0075\u005b\u005c\u0049\u0049\u0029\u007a\u003d\u0069\u0044\u0056\u0069\u002c\u003c\u002d\u0022\u0066\u002c\u003a\u0025\u0035\u0058\u0074\u003e\u0025\u0037\u0049\u002c\u006f\u0032\u0032\u0039\u002c\u0074\u004a\u0067\u0049\u0048\u0044\u0070\u0020\u0079\u0053\u0075\u0056\u0061\u0050\u0056\u0047\u004e\u0079\u005f\u0076\u003b\u007a\u0026\u005e\u0044\u0039\u0025\u0069\u0075\u0033\u0029\u0043\u006a\u0030\u002c\u003f\u005e\u0065\u0052\u007b\u004d\u0044\u0041\u0034\u0050\u0026\u0031\u0049\u006b\u003f\u0075\u0046\u0057\u0057\u0029\u0056\u0041\u002f\u006b\u006f\u0030\u005c\u0029\u0022\u0049\u007e\u0026\u0051\u0025\u0054\u0020\u005d\u002f\u007a\u0020\u007d\u0059\u0056\u003e\u0025\u0020\u003e\u0030\u0032\u0028\u005a\u0070\u0057\u0036\u0047\u0069\u006b\u0061\u0050\u0056\u0054\u0065\u0032\u0021\u0034\u0058\u0035\u0055\u0023\u0038\u0078\u0076\u0059\u0071\u004d\u007d\u002d\u0033\u0061\u0071\u0068\u0042\u0052\u007b\u007d\u004a\u006b\u0029\u0068\u005d\u0049\u003e\u002d\u0077\u0025\u006c\u002b\u006c\u005e\u0069\u0032\u0023\u005a\u0043\u0045\u0051\u0050\u0079\u0069\u003e\u0046\u0049\u006b\u0053\u0028\u004a\u0053\u0066\u0066\u003b\u0048\u0042\u004c\u0020\u002a\u0072\u003c\u0055\u005e\u0027\u007e\u0061\u004b\u0068\u002d\u004b\u0031\u0040\u0074\u0075\u006a\u0079\u0075\u002a\u0070\u0066\u0028\u005e\u004c\u004f\u0053\u0073\u0020\u0049\u0048\u0052\u0034\u0060\u0029\u003e\u0060\u0079\u0070\u0029\u005a\u0036\u0040\u005f\u0042\u0051\u0048\u005a\u0053\u0047\u002e\u0042\u0027\u003e\u0020\u0072\u0068\u0047\u0033\u002a\u0024\u007e\u0070\u0031\u0065\u007b\u0068\u0077\u0062\u005e\u006d\u0025\u0044\u0025\u003c\u002a\u002c\u0049\u004e\u0036\u003b\u005d\u002e\u007a\u0057\u004f\u005b\u0025\u0048\u0046\u004c\u0030\u005f\u005b\u005d\u005a\u0054\u0032\u0078\u0076\u0042\u0054\u0064\u0023\u0039\u0053\u0057\u0057\u0041\u0071\u0065\u003e\u002a\u002c\u0036\u007a\u0027\u007d\u007a\u0049\u0070\u0035\u002a\u007c\u0079\u005b\u0066\u0025\u0051\u0064\u0067\u005f\u0077\u0075\u0033\u004a\u0057\u0052\u0038\u003f\u002a\u0062\u0059\u0042\u0031\u0025\u0063\u0046\u005a\u0049\u0043\u004c\u0050\u0056\u0057\u0077\u0060\u006d\u005d\u002a\u0073\u0022\u006f\u0062\u0061\u0077\u0020\u006d\u003d\u0042\u0028\u0042\u0075\u003e\u004a\u003e\u007b\u0040\u0034\u0024\u0032\u0077\u0074\u0064\u0066\u0079\u002b\u002f\u006a\u0047\u003f\u0022\u0067\u0079\u0034\u0049\u0050\u0066\u0047\u0065\u0071\u004b\u007d\u0043\u0058\u0032\u0068\u0078\u007b\u002b\u0075\u0025\u0045\u007d\u0051\u006e\u002d\u0057\u0064\u0071\u0060\u0027\u004f\u0044\u0057\u0066\u0065\u0056\u0074\u007b\u0074\u003d\u006f\u003e\u0026\u0021\u0024\u0032\u0068\u0072\u005e\u004d\u002d\u007e\u0070\u0023\u0047\u005c\u0076\u005b\u0049\u0022\u0057\u0045\u004a\u0032\u002c\u0059\u004b\u0055\u003a\u0056\u0061\u0056\u0057\u0028\u0077\u002c\u005d\u0039\u003b\u0020\u0067\u004e\u0070\u0040\u004a\u0038\u0023\u0021\u0074\u0064\u0058\u0032\u0039\u0037\u0029\u004a\u0050\u0045\u0033\u0028\u0062\u0054\u0030\u0061\u0048\u004a\u007d\u007d\u0069\u0058\u007c\u0040\u0061\u005b\u0072\u0055\u003a\u0068\u006f\u003a\u0059\u007e\u0033\u0030\u0074\u0049\u004c\u0050\u004b\u0066\u0059\u007b\u002d\u0023\u0077\u0062\u007b\u0075\u005b\u002c\u004a\u007e\u004c\u003c\u0056\u0043\u0036\u003e\u0038\u0072\u0069\u0070\u003e\u0072\u0061\u0040\u0074\u007b\u006b\u005e\u0047\u0023\u0076\u0059\u0053\u003b\u0032\u0060\u003c\u0031\u0048\u005b\u0060\u006f\u0067\u0040\u002e\u005e\u0054\u006f\u0037\u005c\u004f\u0072\u0028\u0063\u0048\u0047\u0064\u0030\u002e\u0031\u0039\u0045\u005f\u006e\u002f\u007c\u002e\u0054\u006d\u0045\u002e\u0065\u0067\u006d\u006f\u005a\u0076\u0060\u004a\u0057\u005a\u0074\u004a\u005a\u0028\u0037\u0072\u0079\u005d\u0058\u0028\u0021\u0040\u0070\u003f\u0048\u0070\u007a\u004a\u004b\u003a\u0029\u0062\u0056\u0076\u006c\u0026\u0038\u005e\u003e\u0055\u0042\u0035\u0038\u005f\u0051\u0069\u0055\u0039\u002d\u0046\u0024\u0055\u003f\u0049\u0030\u007b\u0051\u002f\u0038\u0050\u002a\u0064\u0061\u003a\u007a\u0042\u003b\u0044\u002f\u0074\u0077\u006e\u0070\u0060\u0073\u005d\u007e\u0073\u002c\u0066\u0056\u002b\u0021\u0024\u003b\u0058\u004d\u0048\u006f\u0079\u005a\u005d\u006e\u005f\u007b\u0029\u005a\u007b\u0076\u004c\u0071\u0069\u004e\u0025\u0075\u0073\u0054\u0031\u0041\u0031\u005a\u0045\u003d\u0067\u0042\u0023\u005c\u0073\u005c\u0059\u0031\u006d\u0070\u0033\u004d\u0038\u0034\u0043\u006c\u0051\u004a\u006b\u004e\u0047\u0073\u006a\u0069\u0027\u0061\u0075\u003b\u003e\u0042\u003d\u0065\u003e\u006a\u0026\u0025\u002e\u002a\u0054\u0036\u0036\u0046\u0073\u0078\u0068\u0050\u0058\u0050\u0077\u0039\u0074\u0022\u0020\u0062\u0020\u0062\u0058\u007d\u0061\u0050\u0054\u0047\u006d\u0067\u002b\u0038\u0030\u0057\u005b\u0031\u003c\u0055\u0073\u007e\u003c\u0068\u0067\u0028\u006a\u0051\u0057\u0037\u007c\u0069\u0069\u002e\u0037\u0065\u0048\u004e\u0055\u003e\u004a\u0048\u004d\u0037\u003c\u0020\u006f\u005c\u0029\u0061\u005c\u0070\u0046\u003b\u0030\u0065\u007a\u002e\u0032\u0058\u0074\u0022\u004d\u0077\u0048\u0072\u0033\u007d\u007e\u005d\u003e\u004c\u002a\u004d\u004d\u004e\u0029\u0035\u0030\u0040\u007d\u0028\u004b\u0053\u0057\u0039\u005a\u005b\u002a\u0029\u003f\u0048\u0067\u005d\u003a\u006e\u0024\u0060\u0067\u0053\u007b\u0072\u002e\u0063\u005a\u004c\u0071\u0059\u0064\u0071\u0043\u0026\u0065\u0032\u0043\u004f\u005f\u0026\u0068\u0076\u0079\u0021\u0061\u0070\u0051\u0040\u003c\u0031\u0033\u0046\u0022\u004c\u005f\u0032\u0065\u0079\u007a\u007e\u0072\u0027\u0034\u007c\u004d\u0078\u0021\u003f\u0072\u0073\u004d\u007c\u0077\u007d\u0069\u005b\u003e\u005c\u0059\u005f\u004d\u006b\u0046\u005e\u0040\u0021\u004b\u004e\u0050\u0050\u0047\u0045\u003c\u002d\u0071\u0066\u0059\u003d\u002d\u0065\u0044\u002d\u0031\u0057\u004f\u005a\u0061\u0040\u003f\u006c\u003e\u0030\u003e\u0025\u0052\u0033\u0054\u004d\u0076\u004e\u0070\u006d\u0024\u0054\u0045\u0048\u0030\u003c\u006b\u0041\u0050\u0073\u0069\u0062\u0048\u0068\u0061\u003d\u0035\u0042\u003c\u0039\u0076\u002b\u0048\u007d\u0074\u0050\u007b\u0072\u0065\u0077\u0061\u0059\u0061\u006c\u0025\u005f\u006d\u002e\u004e\u0071\u0057\u0040\u0064\u003c\u0066\u004b\u004f\u0024\u006c\u0046\u007c\u007b\u0058\u0039\u0044\u005d\u0056\u006d\u0076\u0058\u005a\u0057\u0071\u004c\u0076\u0034\u0026\u003d\u0074\u0070\u007e\u0055\u0026\u0030\u005f\u0028\u0044\u002a\u0043\u002b\u0051\u005d\u004c\u0024\u0078\u0044\u006d\u0032\u0028\u0072\u0050\u0025\u002a\u002c\u0074\u005c\u0070\u0052\u0065\u0065\u002f\u007e\u0030\u003a\u003f\u0031\u002c\u002d\u0026\u006f\u0052\u0041\u0065\u0061\u0070\u0037\u004c\u0059\u0022\u0030\u0065\u0027\u0030\u0037\u0050\u0077\u002f\u0069\u004d\u0058\u0035\u004c\u005b\u007d\u0025\u007b\u007a\u005e\u006b\u0067\u0058\u005c\u0041\u0068\u0053\u0070\u0056\u0023\u0074\u0051\u0043\u005f\u005d\u0025\u0039\u007d\u005b\u006d\u0055\u006f\u0033\u0069\u006c\u0066\u0027\u005b\u0055\u0027\u0040\u0057\u003f\u003f\u007d\u0070\u0071\u0025\u0039\u007b\u0034\u0070\u0063\u0045\u0043\u0061\u0051\u0038\u002e\u002a\u004e\u007a\u0032\u006b\u002c\u0027\u0077\u006a\u007a\u006d\u0052\u0053\u0072\u0028\u0048\u0065\u005d\u005c\u0055\u0037\u0076\u0045\u006f\u0062\u004c\u005d\u0050\u0045\u0044\u0061\u0069\u0064\u003e\u002c\u003f\u0048\u0042\u0029\u0056\u0079\u0042\u003f\u003f\u005c\u0026\u002e\u004a\u005d\u0071\u007d\u0078\u007b\u0050\u004b\u0028\u0077\u007b\u004f\u0045\u0039\u0072\u0062\u005e\u0028\u0067\u0075\u0053\u0059\u0028\u003c\u0063\u0074\u003d\u0074\u004f\u0053\u0038\u002f\u0030\u0027\u0074\u0028\u0050\u004e\u007d\u007e\u006b\u0076\u005a\u007b\u0036\u0074\u0058\u0045\u0029\u0065\u0066\u0073\u0067\u0055\u003c\u002c\u007e\u0036\u0074\u004b\u002d\u0048\u003d\u005f\u0040\u0055\u004a\u0078\u0033\u0046\u0075\u0066\u004a\u0051\u006d\u0022\u0046\u0029\u0021\u002e\u002e\u0057\u002f\u0074\u0038\u006f\u0058\u004f\u0066\u0076\u0052\u004b\u0036\u0078\u0034\u0068\u004b\u0078\u0052\u004a\u0043\u0075\u0031\u0027\u0068\u003c\u007a\u0040\u0071\u0037\u006e\u002c\u003d\u0064\u0042\u0041\u0054\u0036\u003b\u0051\u0078\u0053\u006e\u0057\u006d\u0060\u0060\u0038\u004a\u0077\u0067\u0039\u0027\u0071\u0076\u0052\u004f\u002a\u0030\u0034\u0050\u0070\u004c\u0036\u0044\u0025\u0021\u0050\u0041\u0079\u002b\u0044\u0053\u0048\u0020\u0058\u0038\u0027\u0025\u0029\u0040\u007d\u0022\u0060\u002a\u0051\u007d\u005d\u0043\u0069\u0041\u006b\u007b\u006c\u006b\u007c\u004a\u0061\u0073\u007b\u0060\u0042\u0025\u005a\u006e\u0074\u004d\u0029\u0055\u0033\u0059\u0076\u004d\u0062\u0021\u0036\u007e\u0028\u0045\u0076\u002a\u006b\u0035\u0040\u005a\u007a\u0052\u003a\u003b\u0039\u0029\u0037\u007a\u0061\u002b\u0057\u0040\u0039\u0039\u005c\u005f\u002b\u003f\u0032\u004e\u0076\u005f\u0045\u0068\u003d\u0068\u0047\u0079\u003e\u0035\u005b\u0046\u0075\u0037\u0049\u0078\u003d\u002d\u0043\u0035\u005c\u0073\u0074\u0069\u006e\u0064\u0079\u0030\u0044\u0067\u003f\u002b\u0049\u007d\u0038\u003d\u0027\u0077\u003c\u0071\u004f\u0032\u002f\u0065\u002e\u004f\u0027\u003a\u0024\u002a\u0060\u0043\u0045\u004f\u0048\u003b\u0047\u004f\u0056\u0055\u0029\u006f\u0056\u0024\u0059\u005a\u006a\u0042\u0070\u002c\u0038\u0044\u0046\u0051\u0043\u0067\u0052\u0049\u0073\u0035\u0026\u0066\u0060\u003a\u0040\u0029\u0061\u005f\u0076\u0062\u0068\u003c\u007e\u005f\u0025\u0053\u0021\u0076\u004c\u0050\u0059\u0048\u0065\u007a\u0055\u0078\u0068\u0064\u004e\u0031\u0067\u0058\u0030\u0061\u003b\u0045\u0066\u0023\u0034\u0034\u005a\u004e\u007a\u003e\u0069\u0072\u005e\u0074\u0071\u0042\u0020\u004e\u007c\u002e\u0055\u004b\u005a\u0021\u0059\u0079\u004e\u0026\u004e\u005c\u004d\u0046\u0072\u0073\u0023\u0034\u0057\u0045\u0048\u0065\u0043\u0077\u0030\u005c\u0073\u0046\u0056\u0043\u002d\u003f\u0066\u0073\u007e\u005f\u0059\u0035\u003f\u007c\u0025\u0043\u002b\u007b\u006d\u007b\u0049\u0065\u0059\u0031\u005c\u003c\u004d\u006d\u0053\u004b\u0028\u0066\u003e\u006c\u003c\u003f\u004f\u0021\u0031\u0073\u0065\u0042\u002d\u0052\u0046\u002e\u0073\u003f\u007c\u0044\u0069\u0025\u0036\u0028\u003d\u004e\u007a\u003f\u0041\u0027\u0062\u005c\u0071\u0068\u0020\u005f\u0069\u006d\u004c\u004c\u0055\u0077\u0063\u0053\u0049\u002e\u0050\u0077\u004e\u002c\u006c\u0066\u006d\u003a\u006e\u0025\u0078\u0076\u0028\u0038\u0032\u0062\u0057\u0035\u003b\u003b\u007c\u0052\u004a\u003f\u0067\u006c\u0020\u0055\u007d\u007d\u003f\u0079\u005a\u0042\u0057\u0045\u0067\u002b\u005a\u006c\u006f\u0077\u0043\u0060\u005f\u0022\u0041\u0047\u0078\u0070\u003e\u0041\u004a\u0077\u0063\u0069\u002a\u0020\u005b\u0029\u0064\u0073\u0063\u0033\u0042\u005f\u0026\u0070\u0051\u004c\u0069\u003b\u005b\u0046\u006e\u002a\u0033\u0054\u0070\u0060\u004e\u0077\u0052\u0058\u0050\u006f\u0069\u0024\u005c\u004d\u003e\u0072\u006d\u003d\u0031\u003b\u005f\u0073\u002c\u0075\u0052\u006d\u0067\u0057\u007c\u0035\u004c\u0029\u0055\u002c\u0073\u0030\u0071\u0035\u0061\u0042\u0068\u0029\u0057\u0061\u0050\u0045\u002d\u0067\u0074\u005f\u002f\u0026\u006f\u0042\u0055\u007a\u0041\u0038\u0026\u0071\u0035\u004e\u003b\u005f\u0037\u0056\u007a\u002b\u002a\u0054\u0034\u0067\u006c\u0050\u0024\u007c\u0043\u004e\u006d\u0072\u0060\u0065\u0073\u004a\u0078\u0020\u0030\u007c\u0060\u005a\u0029\u006a\u0033\u0071\u0055\u0024\u006f\u0047\u0028\u002a\u0073\u0072\u0025\u004f\u0062\u0049\u0048\u007c\u004e\u003e\u007e\u006a\u0036\u003b\u0032\u0037\u0070\u0022\u0023\u0054\u0062\u006b\u002f\u0035\u0047\u005a\u0068\u0030\u0030\u0033\u007b\u007d\u0060\u0036\u006c\u002c\u0026\u003b\u0064\u006b\u0023\u0069\u0052\u004b\u0024\u0052\u0036\u0048\u0052\u005f\u0062\u0067\u005d\u0079\u003e\u0039\u0070\u0050\u0055\u0042\u004a\u002a\u004c\u0037\u006f\u007b\u0039\u006c\u005c\u0033\u002a\u0023\u0025\u0030\u0029\u004f\u0029\u006c\u0077\u0035\u0048\u0059\u0037\u0027\u005b\u0063\u005e\u0079\u0025\u0064\u005e\u005e\u0021\u0067\u0068\u0064\u0020\u0042\u0074\u0038\u0069\u0053\u0048\u0072\u0076\u007d\u0054\u0056\u0041\u0039\u0024\u002a\u003a\u0021\u003e\u005c\u0058\u0078\u003d\u005b\u002b\u007c\u004c\u0070\u0057\u0024\u0076\u0044\u002d\u0053\u0075\u0021\u0047\u0057\u0051\u0041\u0056\u003f\u007e\u0039\u006b\u0074\u002c\u0068\u0053\u0040\u002f\u0058\u0025\u0025\u0040\u006a\u0079\u0056\u0068\u0037\u0038\u0079\u004a\u006f\u0050\u0074\u0056\u0077\u006b\u006c\u0056\u0044\u0031\u0051\u004b\u0071\u0069\u0023\u0074\u005c\u002d\u0026\u0048\u0073\u0033\u006e\u005f\u004d\u0041\u0022\u0042\u0047\u0030\u0052\u0039\u0020\u0076\u0065\u005b\u006e\u0034\u0046\u0028\u006a\u0074\u0047\u0033\u0052\u0072\u0061\u0061\u007c\u004b\u0076\u0055\u0024\u005d\u006e\u005d\u0065\u0036\u0063\u006b\u0039\u005c\u0035\u006c\u003a\u0074\u003f\u0077\u007e\u002d\u0041\u0054\u004d\u0044\u002d\u003c\u0079\u006b\u0060\u005d\u0041\u002e\u0050\u0040\u007c\u0057\u0075\u0025\u0041\u0046\u0026\u0077\u005e\u0038\u003e\u002d\u007a\u0070\u005a\u0054\u0048\u0026\u002a\u0075\u005d\u0043\u002a\u0072\u0039\u0031\u005b\u0069\u0073\u002e\u003b\u0060\u0033\u003a\u0034\u0058\u0020\u002b\u0049\u004a\u0071\u003b\u0034\u0058\u006f\u0042\u004d\u0050\u004b\u0053\u0030\u004a\u0063\u0051\u0045\u0033\u002a\u0021\u0042\u003f\u0067\u0023\u0024\u0037\u006a\u0026\u0059\u006c\u002c\u0071\u004a\u0038\u0064\u005a\u0038\u0068\u004a\u0028\u003e\u005f\u0032\u004d\u005b\u0076\u006c\u0023\u004b\u006d\u0052\u0050\u0049\u0066\u0055\u003b\u0077\u0079\u0044\u0077\u003d\u0077\u0062\u003a\u006c\u0027\u003a\u002b\u0078\u002e\u0037\u004a\u002c\u0061\u006e\u005a\u0066\u004a\u007d\u0076\u003e\u0032\u004d\u007a\u0036\u0059\u005f\u0044\u006c\u0041\u0071\u002d\u0070\u0069\u0072\u0075\u0024\u0022\u0067\u005f\u005f\u0065\u0031\u007e\u004b\u003e\u0034\u0065\u0048\u0055\u0077\u0074\u005d\u0075\u0027\u0037\u0028\u004e\u0024\u0074\u0049\u002e\u002d\u005a\u0058\u004e\u0029\u0039\u0064\u0040\u002e\u0032\u006a\u0020\u0055\u0076\u0070\u004f\u005f\u007c\u007e\u005b\u0023\u0071\u0065\u0064\u0032\u0060\u004a\u0039\u0077\u004e\u007d\u0035\u0053\u0066\u0051\u003d\u0057\u0029\u006c\u0045\u0077\u006a\u0039\u0068\u0022\u0029\u0039\u0071\u002c\u0042\u0038\u0046\u0073\u0060\u0054\u006f\u0058\u003c\u0041\u004c\u004c\u0053\u003c\u0055\u0033\u004a\u007a\u0053\u0027\u0063\u004e\u005b\u0062\u0033\u0020\u0063\u0025\u0058\u0052\u004c\u0041\u002e\u0034\u0076\u003a\u007b\u002c\u0070\u0069\u006e\u006b\u002c\u003d\u002c\u0076\u002e\u0055\u0070\u0036\u0058\u005e\u0077\u0033\u005f\u005e\u0073\u0035\u005e\u0052\u0024\u0050\u002a\u005f\u004e\u006a\u0070\u0077\u0066\u0071\u0074\u0065\u003c\u005f\u0075\u003b\u004a\u0071\u0068\u002a\u005a\u0039\u007d\u004b\u003b\u0047\u003e\u0053\u0067\u005b\u0020\u0065\u0020\u006a\u0031\u0031\u0022\u006e\u0034\u007a\u0069\u007e\u0054\u002e\u0069\u0022\u006d\u0036\u003d\u003f\u005c\u0053\u006f\u0077\u0038\u0056\u0076\u0023\u004b\u0059\u005b\u0039\u0057\u003f\u007c\u003c\u0050\u0073\u0036\u0074\u0023\u0046\u0029\u006f\u0070\u006f\u0051\u0028\u005c\u0074\u004c\u0050\u0040\u004e\u0054\u004a\u0023\u0039\u005a\u005b\u0028\u0025\u007a\u004b\u0022\u0060\u006c\u0031\u0067\u0025\u007d\u007a\u0056\u0069\u0034\u0066\u006b\u0047\u006c\u0043\u003b\u005e\u003c\u004f\u0034\u006a\u006d\u0064\u0021\u0069\u003c\u002e\u007a\u0031\u0021\u0038\u006c\u0073\u0029\u0077\u0026\u0034\u003d\u0042\u0076\u0034\u003f\u006e\u007b\u0071\u005a\u0023\u004e\u0070\u0053\u0076\u0038\u0060\u0043\u0076\u0072\u0068\u0039\u004c\u004b\u0061\u0051\u005c\u002e\u0055\u004d\u0061\u0077\u0043\u0056\u005c\u007d\u0059\u0036\u005b\u0072\u0027\u0064\u003d\u0058\u0058\u006c\u0027\u006c\u002b\u006a\u0050\u0036\u0076\u0069\u0027\u006a\u0078\u003a\u002a\u0025\u0051\u0052\u0057\u0027\u0027\u0020\u002f\u003e\u007e\u0056\u0062\u0035\u0074\u0066\u005e\u0063\u0023\u0070\u002b\u004b\u003d\u0054\u0023\u002b\u006c\u0039\u0029\u0032\u0034\u0072\u0067\u0032\u0058\u0060\u007a\u0074\u006e\u0033\u005c\u0058\u0045\u0043\u007c\u0044\u004a\u0045\u0022\u006a\u0049\u004a\u003d\u003d\u0061\u002a\u0022\u007a\u0076\u004b\u0060\u004a\u0061\u002f\u0045\u0065\u005f\u003b\u0065\u002d\u0065\u0038\u0059\u0020\u005c\u0074\u0060\u0052\u007d\u0062\u002a\u0032\u0056\u005e\u0041\u0046\u006d\u002c\u0037\u0076\u0059\u002a\u0059\u0075\u0056\u0049\u002e\u0044\u005e\u006d\u006c\u003f\u003a\u0063\u005b\u007a\u0042\u0022\u0045\u0067\u004a\u006d\u0057\u0037\u006b\u0042\u0065\u002c\u0078\u0022\u002f\u0039\u0031\u0026\u0064\u006d\u0022\u0046\u0048\u004a\u0054\u0022\u0043\u0044\u0072\u0073\u0061\u002b\u004b\u005b\u0034\u0067\u004a\u004b\u0064\u0062\u0063\u0038\u0037\u005e\u0031\u006a\u0048\u0022\u0038\u0029\u0039\u003b\u0023\u0078\u007d\u0023\u006d\u0035\u003d\u0057\u0025\u0044\u0045\u0038\u004a\u0042\u0068\u005c\u0038\u0046\u0022\u0028\u0029\u0032\u0022\u0029\u002c\u002f\u002f\u0040\u0046\u005f\u0046\u0045\u0077\u0078\u0075\u004d\u003c\u0020\u005b\u0075\u0066\u0074\u0075\u003e\u0057\u0050\u0047\u006f\u004b\u0048\u0040\u0052\u003b\u0078\u003b\u0037\u007c\u0078\u0039\u0074\u0069\u005e\u0047\u004c\u0056\u006d\u0063\u0046\u0063\u0040\u0061\u0042\u007e\u0061\u007a\u0033\u003e\u0021\u0074\u0028\u005d\u0034\u0046\u0071\u0071\u0035\u0027\u004f\u002a\u0064\u007c\u0076\u0057\u0050\u005f\u003f\u0030\u0042\u0078\u0058\u002f\u0072\u0024\u005d\u0035\u002b\u003d\u007a\u0061\u007b\u0044\u0055\u0060\u0028\u0034\u0063\u0070\u0072\u0063\u0061\u0044\u003b\u007a\u003b\u0030\u0052\u0029\u0067\u0023\u002d\u0061\u0057\u003d\u0058\u0034\u006f\u004d\u0070\u0020\u007c\u0039\u0026\u0062\u0029\u0021\u003e\u0075\u0062\u006d\u0067\u0075\u0051\u003b\u003f\u0045\u002a\u0022\u004f\u0064\u002d\u0034\u0028\u0024\u0079\u002a\u003e\u0021\u0054\u004d\u0066\u0046\u007e\u003f\u0039\u0051\u0056\u0040\u007c\u0068\u0065\u0074\u0045\u0064\u006e\u004e\u0045\u004c\u0079\u0062\u0074\u004f\u0036\u006a\u004b\u0036\u0054\u0072\u003b\u0064\u002b\u005c\u0069\u0053\u0048\u0024\u007b\u0022\u0043\u004a\u006a\u002f\u006a\u0027\u0064\u0028\u005a\u0035\u0074\u0070\u0042\u0022\u0068\u0069\u0069\u004d\u004f\u0058\u007a\u0029\u0062\u0033\u0073\u005c\u002b\u0045\u003b\u0060\u0070\u0032\u005c\u0046\u0075\u007a\u0062\u0062\u004b\u005e\u0059\u0052\u0021\u0060\u0034\u0074\u003f\u0048\u0032\u0035\u0039\u004a\u0037\u0077\u007e\u0026\u0031\u0054\u0065\u004a\u0043\u0063\u0071\u0063\u0040\u003d\u005f\u0068\u0049\u002e\u0038\u0076\u0027\u0038\u0030\u0034\u0043\u0033\u002a\u0036\u0065\u0035\u007e\u0057\u007a\u0034\u0045\u0070\u0028\u0020\u0067\u0070\u0067\u0039\u0062\u0035\u0073\u0047\u0022\u004f\u003e\u0076\u0048\u006f\u0031\u0051\u0063\u0030\u0041\u0043\u0029\u003f\u006f\u0059\u0047\u0033\u0037\u0056\u0075\u0065\u0038\u0021\u006f\u0073\u0062\u003f\u0032\u0057\u0031\u003b\u006a\u003a\u0072\u002c\u003d\u005a\u0030\u0028\u0079\u006f\u0048\u0057\u003c\u004f\u003b\u0031\u0076\u002d\u0041\u002d\u007e\u007d\u005d\u005d\u0048\u0055\u0032\u0027\u004d\u005d\u003c\u006b\u0049\u007a\u0027\u007a\u004d\u0044\u0023\u0037\u0033\u0073\u0036\u002c\u0032\u006d\u0048\u006b\u0027\u0028\u0021\u0062\u0053\u0075\u006a\u0051\u0065\u0060\u0032\u005d\u0067\u0051\u0039\u0054\u005f\u004f\u006f\u0042\u0039\u006d\u005f\u0041\u0059\u0058\u006e\u005e\u003d\u0027\u0068\u0029\u0040\u0042\u0047\u005b\u0078\u0025\u0063\u0023\u0031\u003c\u002e\u004c\u0064\u0044\u0043\u002f\u004b\u0023\u0068\u0072\u0029\u0065\u0032\u003c\u006a\u006c\u0051\u0026\u0026\u0075\u0068\u002d\u0029\u006c\u0060\u004f\u007e\u004b\u0063\u0031\u0051\u0079\u0064\u006c\u004c\u006b\u0029\u0072\u0042\u0031\u0041\u0061\u0023\u002e\u002c\u007c\u0026\u0021\u0043\u003b\u0046\u0044\u0040\u004f\u0039\u0023\u0028\u0058\u0077\u004c\u0076\u0039\u0050\u0032\u007a\u0022\u0056\u0043\u003e\u006d\u0045\u0068\u0060\u0071\u0046\u002d\u0040\u0048\u0063\u006f\u0051\u0031\u0041\u0070\u0068\u005d\u0046\u002c\u005c\u004a\u0040\u006d\u0050\u0038\u0067\u003b\u0046\u006e\u0030\u0055\u006b\u0023\u007b\u003f\u0065\u0026\u007b\u005a\u0043\u006d\u0070\u0043\u0072\u006a\u004b\u002c\u0052\u006b\u0022\u0023\u007d\u0035\u002a\u004c\u0072\u003b\u0026\u0046\u002d\u0071\u0039\u004d\u007e\u0028\u003f\u002c\u0078\u0047\u0041\u003e\u005e\u0026\u0061\u005e\u0021\u002b\u003b\u0029\u0039\u0051\u0044\u005b\u0076\u004b\u0056\u0035\u0030\u0073\u0033\u0039\u0065\u0042\u0033\u0021\u0056\u004c\u0063\u0040\u0039\u0048\u0044\u0035\u005d\u0025\u003b\u0035\u005f\u002a\u0065\u0058\u0056\u0046\u005b\u006d\u0073\u003e\u0047\u0048\u0023\u0078\u002f\u0079\u0039\u0052\u003b\u0071\u0053\u0029\u004f\u002d\u0049\u003a\u007e\u0072\u007c\u0039\u0043\u004d\u0021\u004c\u0075\u006e\u003f\u004d\u0040\u005b\u0066\u004b\u0067\u0035\u0030\u0050\u0032\u0023\u002a\u0033\u003a\u006c\u0077\u0032\u0020\u0072\u0025\u007a\u0067\u007c\u003e\u0030\u0057\u0031\u0034\u0022\u006b\u0043\u0034\u0026\u0061\u003f\u0072\u0054\u0071\u002a\u0043\u005a\u0045\u0048\u0028\u0022\u0031\u0052\u003a\u004f\u0070\u0030\u007d\u0063\u0029\u0063\u002c\u004f\u0057\u0070\u004a\u0064\u0025\u002b\u0062\u0030\u006c\u0068\u004c\u0070\u0059\u0039\u005a\u0049\u0028\u0061\u0070\u002f\u0033\u0039\u0072\u0031\u0025\u0076\u0025\u0035\u004a\u0059\u0072\u0032\u002d\u004b\u0029\u0047\u0070\u003b\u0043\u0026\u0031\u003e\u0055\u002f\u0069\u005c\u003c\u0053\u005c\u0039\u003f\u0069\u0071\u005a\u0025\u0067\u0046\u005a\u0046\u0075\u0038\u0024\u003a\u004b\u0054\u006e\u007d\u0076\u006f\u0074\u007b\u0077\u006f\u0027\u0024\u0056\u002a\u0073\u006d\u0050\u0035\u0059\u005c\u0021\u0060\u0056\u0071\u0023\u0032\u002a\u003c\u0048\u006f\u007b\u0076\u005e\u0046\u0068\u0050\u0043\u0029\u0063\u0054\u0051\u004b\u0029\u0020\u0071\u003c\u0055\u0066\u005d\u002f\u004c\u0025\u0040\u006b\u005b\u007b\u004c\u004f\u0020\u007d\u0071\u0027\u002a\u0027\u0021\u0034\u004b\u0027\u0046\u002e\u0071\u0021\u005c\u003e\u0032\u002e\u0062\u005c\u0059\u003a\u0064\u007d\u002a\u0052\u0035\u0024\u002e\u0050\u0071\u0039\u0041\u005a\u004a\u006d\u0065\u0071\u0036\u006f\u0024\u0039\u0048\u0063\u0071\u0044\u0045\u0054\u0066\u0037\u0020\u002e\u0069\u003d\u0058\u0039\u006f\u0025\u003a\u005c\u0057\u0041\u0050\u003e\u0032\u0033\u0038\u0024\u006a\u0056\u002a\u004f\u0071\u0072\u006b\u0048\u006d\u0053\u0024\u0048\u0037\u004d\u0061\u0052\u002a\u0023\u006b\u007c\u006e\u0058\u0061\u002f\u0045\u007d\u0058\u006d\u002b